resource "aws_vpc" "main" {
  cidr_block           = "10.20.0.0/16"
  enable_dns_hostnames = true
  tags = { Name = "prod" }
}

locals {
  azs = ["us-east-1a", "us-east-1b", "us-east-1c"]
  # 10.20.0.0/16 → /20 blocks (4,091 usable each)
  private = [for i, az in local.azs : cidrsubnet("10.20.0.0/16", 4, i)]       # 10.20.0.0/20, 10.20.16.0/20, 10.20.32.0/20
  public  = [for i, az in local.azs : cidrsubnet("10.20.0.0/16", 8, 240 + i)] # 10.20.240.0/24 ...
}

resource "aws_internet_gateway" "igw" { vpc_id = aws_vpc.main.id }
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }
}
resource "aws_route_table_association" "pub_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private_a.id, aws_route_table.private_b.id]
}
